def fit_stump(X, r):
    if not X or len(X) != len(r) or any(len(row) != len(X[0]) for row in X):
        raise ValueError('need rows of equal length, one target each')
    candidates = []
    for f in range(len(X[0])):
        values = sorted(set(row[f] for row in X))
        for a, b in zip(values, values[1:]):
            t = (a + b) / 2
            left = [v for row, v in zip(X, r) if row[f] <= t]
            right = [v for row, v in zip(X, r) if row[f] > t]
            ml, mr = sum(left) / len(left), sum(right) / len(right)
            sse = sum((v - ml) * (v - ml) for v in left) + sum((v - mr) * (v - mr) for v in right)
            candidates.append((sse, f, t, ml, mr))
    if not candidates:
        return None
    low = min(c[0] for c in candidates)
    sse, f, t, ml, mr = next(c for c in candidates if c[0] <= low + 1e-9)
    return f, t, ml, mr


